export function createSoundTrails(set='sounds'){
 if(!['sounds','vowels'].includes(set))return null;
 const material=set==='vowels'?vowelSource:source,tryWords=set==='vowels'?['pin','pine']:['mix','quiz'];
 return {source:structuredClone(material),selected:set==='vowels'?'cap':'fox',compare:false,
  work:Object.fromEntries(Object.keys(material.words).map(id=>[id,{count:0,frame:0,tool:tryWords.includes(id)?'try':'model'}]))};
}
export function soundTrailPair(v){
 return Object.values(v.source.pairs).find(p=>p.ids.includes(v.selected))||null;
}
export function changeSoundTrail(v,action,value){
 const w=v?.work?.[v.selected];if(!w)return null;
 if(action==='word'){
  if(typeof value!=='string'||!Object.hasOwn(v.source.words,value))return null;
  return {...v,selected:value,compare:false};
 }
 if(action==='back')return v.compare?{...v,compare:false}:null;
 if(action==='compare')return !v.compare&&soundTrailPair(v)?{...v,compare:true}:null;
 if(v.compare)return null;
 let changed;
 if(action==='model'||action==='try')changed={...w,tool:action};
 else if(action==='counter'){
  if(w.tool!=='try'||![-1,1].includes(value)||w.count+value<0||w.count+value>6)return null;
  changed={...w,count:w.count+value};
 }else if(action==='step'){
  if(w.tool!=='model'||![-1,1].includes(value)||w.frame+value<0||w.frame+value>4)return null;
  changed={...w,frame:w.frame+value};
 }else return null;
 return {...v,work:{...v.work,[v.selected]:changed}};
}
export function soundTrailReference(v,id=v.selected,frame=v.work[id]?.frame??0){
 const w=v.source.words[id];if(!w||!Number.isInteger(frame)||frame<0||frame>4)return null;
 const active=frame===4?w.groups:frame>0?[w.groups[frame-1]]:[];
 return {word:w,frame,letters:active.flatMap(g=>g.letters),sounds:active.flatMap(g=>g.sounds)};
}
export const soundTrailCounterLine=n=>n===1?'You placed 1 counter.':'You placed '+n+' counters.';
